import { readFileSync } from 'fs';
import { join } from 'path';

const KNOWN_PLATFORM_IDS = ['google','meta','google_ads','ga4','meta_ads','meta_pages','tiktok','tiktok_ads','linkedin','linkedin_ads','linkedin_pages','snapchat','snapchat_ads','instagram','kit','beehiiv','mailchimp','pinterest','klaviyo','shopify','zapier','google_tag_manager','google_merchant_center','google_search_console','google_business_profile','whatsapp_business','youtube_studio','display_video_360'];
const ID_ALTERNATION = [...KNOWN_PLATFORM_IDS].sort((a,b)=>b.length-a.length).join('|');
const QUOTED_RUN_RE = new RegExp(`['"](?:${ID_ALTERNATION})['"]`, 'g');
function stripComments(source) {
  return source.replace(/\/\*[\s\S]*?\*\//g, m=>m.replace(/[^\n]/g,' ')).replace(/\/\/[^\n]*/g, m=>m.replace(/[^\n]/g,' '));
}
function findQuotedRuns(clean) {
  const matches = [...clean.matchAll(QUOTED_RUN_RE)];
  const runs = []; let current = null;
  for (let i = 1; i < matches.length; i++) {
    const previous = matches[i-1];
    const gap = clean.slice(previous.index + previous[0].length, matches[i].index);
    if (/^\s*,\s*$/.test(gap)) {
      if (!current) current = { index: previous.index, count: 1 };
      current.count += 1;
    } else if (current) { runs.push(current); current = null; }
  }
  if (current) runs.push(current);
  return runs.filter(r => r.count >= 3);
}
function findSwitchDispatch(clean) {
  const distinct = new Set(); let firstIndex = Infinity;
  for (const id of KNOWN_PLATFORM_IDS) {
    const caseRe = new RegExp(`\\bcase\\s*['"]${id}['"]`, 'g');
    let match; while ((match = caseRe.exec(clean)) !== null) {
      distinct.add(id); if (match.index < firstIndex) firstIndex = match.index;
    }
  }
  return distinct.size >= 3 ? { index: firstIndex, distinct: distinct.size } : null;
}
function lineOf(clean, index) { return clean.slice(0, index).split('\n').length; }
for (const rel of ['apps/api/src/services/access-request.service.ts','apps/api/src/services/client.service.ts']) {
  const clean = stripComments(readFileSync(rel,'utf8'));
  const runs = findQuotedRuns(clean);
