import { describe, expect, it } from 'vitest';
import { ASSET_SELECTING_PRODUCTS } from '../asset-selecting-products.js';
import { getSelectedAssetCount, hasNoAssetsSignal } from '../product-selection-signals.js';

/**
 * Characterization for the shared selection/inventory helpers extracted from
 * access-request.service.ts and client.service.ts (review card 2 / DEC-015).
 *
 * Instagram counts only instagramAccounts — the client.service / wizard
 * semantics. access-request previously counted sibling Meta asset kinds for
 * Instagram; that drift is closed by this module.
 */

describe('getSelectedAssetCount', () => {
  it('covers every ASSET_SELECTING_PRODUCTS member without throwing', () => {
    for (const product of ASSET_SELECTING_PRODUCTS) {
      expect(getSelectedAssetCount(product, {})).toBe(0);
    }
  });

  it('counts Meta ads blob fields for meta_ads', () => {
    expect(
      getSelectedAssetCount('meta_ads', {
        adAccounts: ['a1'],
        pages: ['p1'],
        instagramAccounts: ['ig1'],
        catalogs: ['c1'],
        datasets: ['d1'],
      })
    ).toBe(5);
  });

  it('counts only instagramAccounts for instagram (not sibling Meta kinds)', () => {
    expect(
      getSelectedAssetCount('instagram', {
        adAccounts: ['a1'],
        pages: ['p1'],
        instagramAccounts: ['ig1', 'ig2'],
        catalogs: ['c1'],
        datasets: ['d1'],
      })
    ).toBe(2);
  });

  it('counts pages only for meta_pages', () => {
    expect(
      getSelectedAssetCount('meta_pages', {
        pages: ['p1', 'p2'],
        adAccounts: ['a1'],
      })
    ).toBe(2);
  });

  it('counts Google product-specific asset arrays', () => {
    expect(getSelectedAssetCount('google_ads', { adAccounts: ['1'], pages: ['2'] })).toBe(2);
    expect(getSelectedAssetCount('ga4', { properties: ['p'] })).toBe(1);
    expect(getSelectedAssetCount('google_business_profile', { businessAccounts: ['b'] })).toBe(1);
    expect(getSelectedAssetCount('google_tag_manager', { containers: ['c'] })).toBe(1);
    expect(getSelectedAssetCount('google_search_console', { sites: ['s'] })).toBe(1);
    expect(getSelectedAssetCount('google_merchant_center', { merchantAccounts: ['m'] })).toBe(1);
  });

  it('counts LinkedIn ads/pages via the shared Meta-shaped blob fields', () => {
    expect(
      getSelectedAssetCount('linkedin_ads', {
        adAccounts: ['a'],
        pages: ['p'],
      })
    ).toBe(2);
    expect(getSelectedAssetCount('linkedin_pages', { pages: ['p1', 'p2'] })).toBe(2);
  });

  it('prefers TikTok selectedAdvertiserIds, then adAccounts, then advertisers', () => {
    expect(
      getSelectedAssetCount('tiktok', {
        selectedAdvertiserIds: ['s1', 's2'],
        adAccounts: ['a1'],
        advertisers: ['x'],
      })
    ).toBe(2);
    expect(
      getSelectedAssetCount('tiktok_ads', {
        adAccounts: ['a1'],
        advertisers: ['x', 'y'],
      })
    ).toBe(1);
    expect(getSelectedAssetCount('tiktok', { advertisers: ['x', 'y', 'z'] })).toBe(3);
  });

  it('returns 0 for unknown products', () => {
    expect(getSelectedAssetCount('not_a_product', { adAccounts: ['a'] })).toBe(0);
  });
});

describe('hasNoAssetsSignal', () => {
  it('is true when availableAssetCount is 0 for inventory-tracked products', () => {
    for (const product of [
      'google_ads',
      'ga4',
      'google_business_profile',
      'google_tag_manager',
      'google_search_console',
      'google_merchant_center',
      'meta_pages',
      'linkedin_ads',
      'linkedin_pages',
    ]) {
      expect(hasNoAssetsSignal(product, { availableAssetCount: 0 })).toBe(true);
      expect(hasNoAssetsSignal(product, { availableAssetCount: 3 })).toBe(false);
      expect(hasNoAssetsSignal(product, {})).toBe(false);
    }
  });

  it('uses availableAdvertisers emptiness for TikTok products', () => {
    expect(hasNoAssetsSignal('tiktok', { availableAdvertisers: [] })).toBe(true);
    expect(hasNoAssetsSignal('tiktok_ads', { availableAdvertisers: ['a'] })).toBe(false);
    expect(hasNoAssetsSignal('tiktok', {})).toBe(false);
  });

  it('is false for meta_ads and instagram (no inventory signal today)', () => {
    expect(hasNoAssetsSignal('meta_ads', { availableAssetCount: 0 })).toBe(false);
    expect(hasNoAssetsSignal('instagram', { availableAssetCount: 0 })).toBe(false);
  });
});

/**
 * Shared selection / inventory signals for asset-selecting products.
 *
 * Single home for the helpers previously duplicated (and drifted) between
 * access-request.service.ts and client.service.ts. Review card 2 / DEC-015:
 * encode per-product dispatch as an unquoted-key table so the platform-id
 * walker does not need an allowlist entry for this module.
 *
 * Instagram counts only `instagramAccounts` (client-detail / wizard truth).
 */

type AssetBlob = Record<string, unknown>;

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function sumFieldLengths(assets: AssetBlob, fields: readonly string[]): number {
  let total = 0;
  for (const field of fields) {
    total += asArray(assets[field]).length;
  }
  return total;
}

const META_SHAPED_SELECTION_FIELDS = [
  'adAccounts',
  'pages',
  'instagramAccounts',
  'catalogs',
  'datasets',
] as const;

function countMetaShapedSelection(assets: AssetBlob): number {
  return sumFieldLengths(assets, META_SHAPED_SELECTION_FIELDS);
}

function countTikTokSelection(assets: AssetBlob): number {
  return (
    asArray(assets.selectedAdvertiserIds).length ||
    asArray(assets.adAccounts).length ||
    asArray(assets.advertisers).length ||
    0
  );
}

function availableAssetCountIsZero(assets: AssetBlob): boolean {
  return assets.availableAssetCount === 0;
}

function tikTokInventoryEmpty(assets: AssetBlob): boolean {
  return Array.isArray(assets.availableAdvertisers) && assets.availableAdvertisers.length === 0;
}

interface ProductSelectionSignal {
  countSelected: (assets: AssetBlob) => number;
  hasNoAssets?: (assets: AssetBlob) => boolean;
}

/**
 * Unquoted object keys — outside the walker's quoted-run and case-dispatch
 * detectors (DEC-015 Phase 3). Adding a product here is the sanctioned edit.
 */
const PRODUCT_SELECTION_SIGNALS: Readonly<Record<string, ProductSelectionSignal>> = {
  google_ads: {
    countSelected: countMetaShapedSelection,
    hasNoAssets: availableAssetCountIsZero,
  },
  meta_ads: {
    countSelected: countMetaShapedSelection,
  },
  linkedin_ads: {
    countSelected: countMetaShapedSelection,
    hasNoAssets: availableAssetCountIsZero,
  },
  linkedin_pages: {
    countSelected: countMetaShapedSelection,
    hasNoAssets: availableAssetCountIsZero,
  },
  instagram: {
    countSelected: (assets) => asArray(assets.instagramAccounts).length,
  },
  meta_pages: {
    countSelected: (assets) => asArray(assets.pages).length,
    hasNoAssets: availableAssetCountIsZero,
  },
  ga4: {
    countSelected: (assets) => asArray(assets.properties).length,
    hasNoAssets: availableAssetCountIsZero,
  },
  google_business_profile: {
    countSelected: (assets) => asArray(assets.businessAccounts).length,
    hasNoAssets: availableAssetCountIsZero,
  },
  google_tag_manager: {
    countSelected: (assets) => asArray(assets.containers).length,
    hasNoAssets: availableAssetCountIsZero,
  },
  google_search_console: {
    countSelected: (assets) => asArray(assets.sites).length,
    hasNoAssets: availableAssetCountIsZero,
  },
  google_merchant_center: {
    countSelected: (assets) => asArray(assets.merchantAccounts).length,
    hasNoAssets: availableAssetCountIsZero,
  },
  tiktok: {
    countSelected: countTikTokSelection,
    hasNoAssets: tikTokInventoryEmpty,
  },
  tiktok_ads: {
    countSelected: countTikTokSelection,
    hasNoAssets: tikTokInventoryEmpty,
  },
};

export function getSelectedAssetCount(product: string, assets: AssetBlob): number {
  const signal = PRODUCT_SELECTION_SIGNALS[product];
  return signal ? signal.countSelected(assets) : 0;
}

export function hasNoAssetsSignal(product: string, assets: AssetBlob): boolean {
  const signal = PRODUCT_SELECTION_SIGNALS[product];
  return signal?.hasNoAssets ? signal.hasNoAssets(assets) : false;
}

