/**
 * Per-product verification dispatch for platform-native authorization checks
 * (architecture review card 2 / U3).
 *
 * Unquoted-key table — outside the platform-id walker's case-dispatch detector.
 */

import type { AccessLevel } from '@agency-platform/shared';
import { metaConnector } from '@/services/connectors/meta.js';
import { googleAdsConnector } from '@/services/connectors/google-ads.js';
import { ga4Connector } from '@/services/connectors/ga4.js';

export interface PlatformVerificationJobData {
  clientEmail: string;
  requiredAccessLevel: AccessLevel;
  agencyIdentity: {
    email?: string;
    businessId?: string;
  };
}

export interface PlatformVerificationResult {
  hasAccess: boolean;
  accessLevel: AccessLevel;
  accounts?: Array<{
    id: string;
    name: string;
    status: string;
    permissions: string[];
  }>;
  properties?: Array<{
    id: string;
    name: string;
    displayName: string;
    permissions: string[];
  }>;
  businessName?: string;
  assets?: Array<{
    type: string;
    id: string;
    name: string;
    permissions?: string[];
  }>;
  error?: string;
}

type PlatformVerificationHandler = (
  accessToken: string,
  jobData: PlatformVerificationJobData,
  verificationId: string
) => Promise<PlatformVerificationResult>;

async function verifyMetaAccess(
  accessToken: string,
  jobData: PlatformVerificationJobData
): Promise<PlatformVerificationResult> {
  return metaConnector.verifyClientAccess(
    accessToken,
    jobData.agencyIdentity.businessId || '',
    jobData.clientEmail,
    jobData.requiredAccessLevel
  );
}

/**
 * Unquoted object keys — walker-safe (DEC-015 Phase 3).
 */
const PLATFORM_VERIFICATION_HANDLERS: Readonly<
  Record<string, PlatformVerificationHandler>
> = {
  meta_ads: async (accessToken, jobData) => verifyMetaAccess(accessToken, jobData),
  meta_pages: async (accessToken, jobData) => verifyMetaAccess(accessToken, jobData),
  google_ads: async (accessToken, jobData) =>
    googleAdsConnector.verifyClientAccess(
      accessToken,
      jobData.clientEmail,
      jobData.requiredAccessLevel
    ),
  ga4: async (accessToken, jobData) =>
    // Property ID would come from client confirmation data; MVP uses empty.
    ga4Connector.verifyClientAccess(
      accessToken,
      jobData.clientEmail,
      '',
      jobData.requiredAccessLevel
    ),
};

export async function verifyPlatformAccess(
  platform: string,
  accessToken: string,
  jobData: PlatformVerificationJobData,
  verificationId: string
): Promise<PlatformVerificationResult> {
  const handler = PLATFORM_VERIFICATION_HANDLERS[platform];
  if (!handler) {
    return {
      hasAccess: false,
      accessLevel: 'read_only',
      error: `Unsupported platform: ${platform}`,
    };
  }
  return handler(accessToken, jobData, verificationId);
}

/** Test/helper: known dispatch keys for completeness checks. */
export function verificationHandlerPlatforms(): readonly string[] {
  return Object.keys(PLATFORM_VERIFICATION_HANDLERS);
}

import { beforeEach, describe, expect, it, vi } from 'vitest';

const metaVerify = vi.fn();
const googleAdsVerify = vi.fn();
const ga4Verify = vi.fn();

vi.mock('@/services/connectors/meta.js', () => ({
  metaConnector: { verifyClientAccess: (...args: unknown[]) => metaVerify(...args) },
}));

vi.mock('@/services/connectors/google-ads.js', () => ({
  googleAdsConnector: { verifyClientAccess: (...args: unknown[]) => googleAdsVerify(...args) },
}));

vi.mock('@/services/connectors/ga4.js', () => ({
  ga4Connector: { verifyClientAccess: (...args: unknown[]) => ga4Verify(...args) },
}));

import {
  verificationHandlerPlatforms,
  verifyPlatformAccess,
} from '../platform-verification-handlers.js';

const jobData = {
  clientEmail: 'client@example.com',
  requiredAccessLevel: 'manage' as const,
  agencyIdentity: { businessId: 'bm-1', email: 'agency@example.com' },
};

describe('verifyPlatformAccess', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    metaVerify.mockResolvedValue({ hasAccess: true, accessLevel: 'manage' });
    googleAdsVerify.mockResolvedValue({ hasAccess: true, accessLevel: 'manage' });
    ga4Verify.mockResolvedValue({ hasAccess: true, accessLevel: 'manage' });
  });

  it('dispatches meta_ads and meta_pages through the Meta connector', async () => {
    await verifyPlatformAccess('meta_ads', 'token', jobData, 'v1');
    await verifyPlatformAccess('meta_pages', 'token', jobData, 'v2');

    expect(metaVerify).toHaveBeenCalledTimes(2);
    expect(metaVerify).toHaveBeenCalledWith('token', 'bm-1', 'client@example.com', 'manage');
    expect(googleAdsVerify).not.toHaveBeenCalled();
  });

  it('dispatches google_ads through the Google Ads connector', async () => {
    await verifyPlatformAccess('google_ads', 'token', jobData, 'v1');
    expect(googleAdsVerify).toHaveBeenCalledWith('token', 'client@example.com', 'manage');
  });

  it('dispatches ga4 through the GA4 connector', async () => {
    await verifyPlatformAccess('ga4', 'token', jobData, 'v1');
    expect(ga4Verify).toHaveBeenCalledWith('token', 'client@example.com', '', 'manage');
  });

  it('returns unsupported for unknown platforms', async () => {
    await expect(verifyPlatformAccess('tiktok', 'token', jobData, 'v1')).resolves.toEqual({
      hasAccess: false,
      accessLevel: 'read_only',
      error: 'Unsupported platform: tiktok',
    });
  });

  it('exposes the four dispatched product keys', () => {
    expect(verificationHandlerPlatforms().sort()).toEqual(
      ['ga4', 'google_ads', 'meta_ads', 'meta_pages'].sort()
    );
  });
});

