/**
 * Pure helpers for Meta invite resume / prefill (architecture card 3 / U6).
 * Session effects stay in useMetaResumePrefill; this file has no React.
 */

import type { MetaSelectionBlob } from '@/components/client-auth/meta-selection-blob';
import {
  hasSelectableAssets,
  type InviteSelectionPrefill,
} from '@/lib/invite/landing-state';

export function hasRetainedMetaSelection(
  expected: InviteSelectionPrefill | null,
  actual: MetaSelectionBlob | undefined
): boolean {
  if (!expected || !actual) return false;
  const matches = (saved: string[], selected: string[]) =>
    saved.length === selected.length && saved.every((id) => selected.includes(id));
  return (
    matches(expected.adAccounts, actual.adAccounts) &&
    matches(expected.pages, actual.pages) &&
    matches(expected.instagramAccounts, actual.instagramAccounts) &&
    matches(expected.catalogs, actual.catalogs) &&
    matches(expected.datasets, actual.datasets)
  );
}

/** Serialized key for popup-resume prefill sync (#10). Empty when no prefill. */
export function invitePrefillSyncKey(
  metaNeedsGrantStep: boolean,
  initialMetaSelections: InviteSelectionPrefill | null | undefined
): string {
  if (!metaNeedsGrantStep || !hasSelectableAssets(initialMetaSelections)) {
    return '';
  }
  return JSON.stringify(initialMetaSelections);
}

/** Seed groupAssets when the invite payload already carries Meta selections. */
export function buildMetaGroupAssetsSeedFromPrefill(
  prefill: InviteSelectionPrefill,
  businessId?: string
): Record<string, MetaSelectionBlob> {
  const selectedAssets: MetaSelectionBlob = {
    ...prefill,
    selectedBusinessId: businessId,
    selectedAdAccountsWithNames: prefill.adAccounts.map((id) => ({ id, name: id })),
    selectedPagesWithNames: prefill.pages.map((id) => ({ id, name: id })),
    selectedInstagramWithNames: prefill.instagramAccounts.map((id) => ({ id, name: id })),
    selectedCatalogsWithNames: prefill.catalogs.map((id) => ({ id, name: id })),
    selectedDatasetsWithNames: prefill.datasets.map((id) => ({ id, name: id })),
  };
  return {
    meta_ads: selectedAssets,
    meta_pages: selectedAssets,
    instagram: selectedAssets,
  };
}

import { describe, expect, it } from 'vitest';
import {
  buildMetaGroupAssetsSeedFromPrefill,
  hasRetainedMetaSelection,
  invitePrefillSyncKey,
} from '../meta-resume-prefill';
import type { InviteSelectionPrefill } from '@/lib/invite/landing-state';

const prefill: InviteSelectionPrefill = {
  adAccounts: ['act-1'],
  pages: ['page-1'],
  instagramAccounts: ['ig-1'],
  catalogs: [],
  datasets: [],
};

describe('meta-resume-prefill', () => {
  it('reports retained selection only when every list matches', () => {
    expect(
      hasRetainedMetaSelection(prefill, {
        ...prefill,
        selectedBusinessId: 'biz-1',
      })
    ).toBe(true);

    expect(
      hasRetainedMetaSelection(prefill, {
        ...prefill,
        adAccounts: ['act-2'],
        selectedBusinessId: 'biz-1',
      })
    ).toBe(false);

    expect(hasRetainedMetaSelection(null, prefill as never)).toBe(false);
  });

  it('builds a sync key only when Meta grant step has selectable prefill', () => {
    expect(invitePrefillSyncKey(true, prefill)).toBe(JSON.stringify(prefill));
    expect(invitePrefillSyncKey(false, prefill)).toBe('');
    expect(
      invitePrefillSyncKey(true, {
        adAccounts: [],
        pages: [],
        instagramAccounts: [],
        catalogs: [],
        datasets: [],
      })
    ).toBe('');
  });

  it('seeds meta_ads / meta_pages / instagram from the same prefill blob', () => {
    const seed = buildMetaGroupAssetsSeedFromPrefill(prefill, 'biz-1');
    expect(seed.meta_ads?.selectedBusinessId).toBe('biz-1');
    expect(seed.meta_ads?.selectedAdAccountsWithNames).toEqual([{ id: 'act-1', name: 'act-1' }]);
    expect(seed.meta_pages).toBe(seed.meta_ads);
    expect(seed.instagram).toBe(seed.meta_ads);
  });
});

'use client';

/**
 * Meta invite resume / prefill session state (architecture card 3 / U6).
 * Keeps popup-resume sync (#10) and one-shot saved-share marking out of the wizard body.
 */

import { useEffect, useRef, useState } from 'react';
import type { MetaSelectionBlob } from '@/components/client-auth/meta-selection-blob';
import type { InviteSelectionPrefill } from '@/lib/invite/landing-state';
import {
  hasRetainedMetaSelection,
  invitePrefillSyncKey,
} from '@/lib/invite/meta-resume-prefill';

export interface UseMetaResumePrefillArgs {
  metaNeedsGrantStep: boolean;
  initialMetaSelections?: InviteSelectionPrefill | null;
  metaSelectionBlob: MetaSelectionBlob | undefined;
  setAssetsSaved: (saved: boolean) => void;
  setChooseAccountsExpanded: (expanded: boolean) => void;
}

export interface UseMetaResumePrefillResult {
  metaSelectionPrefill: InviteSelectionPrefill | null;
  clearResumePrefill: () => void;
  cancelResumeSavedPending: () => void;
  metaAssetsLoaded: boolean;
  retainedResumeSelection: boolean;
}

export function useMetaResumePrefill({
  metaNeedsGrantStep,
  initialMetaSelections,
  metaSelectionBlob,
  setAssetsSaved,
  setChooseAccountsExpanded,
}: UseMetaResumePrefillArgs): UseMetaResumePrefillResult {
  const hasInitialMetaSelections =
    metaNeedsGrantStep &&
    Boolean(initialMetaSelections) &&
    invitePrefillSyncKey(metaNeedsGrantStep, initialMetaSelections).length > 0;

  const [metaSelectionPrefill, setMetaSelectionPrefill] = useState<InviteSelectionPrefill | null>(
    hasInitialMetaSelections ? (initialMetaSelections as InviteSelectionPrefill) : null
  );

  const resumeSavedPendingRef = useRef(hasInitialMetaSelections);
  const prefillKey = invitePrefillSyncKey(metaNeedsGrantStep, initialMetaSelections);
  const appliedPrefillKeyRef = useRef(prefillKey);

  useEffect(() => {
    if (!prefillKey || appliedPrefillKeyRef.current === prefillKey) return;
    appliedPrefillKeyRef.current = prefillKey;
    setMetaSelectionPrefill(JSON.parse(prefillKey) as InviteSelectionPrefill);
    resumeSavedPendingRef.current = true;
  }, [prefillKey]);

  const metaAssetsLoaded =
    !metaNeedsGrantStep || metaSelectionBlob?.assetsLoaded === true;
  const retainedResumeSelection = hasRetainedMetaSelection(
    metaSelectionPrefill,
    metaSelectionBlob
  );

  useEffect(() => {
    if (!resumeSavedPendingRef.current || !metaAssetsLoaded) return;
    resumeSavedPendingRef.current = false;
    if (retainedResumeSelection) {
      setAssetsSaved(true);
      return;
    }
    setAssetsSaved(false);
    setChooseAccountsExpanded(true);
  }, [
    metaAssetsLoaded,
    metaSelectionBlob,
    retainedResumeSelection,
    setAssetsSaved,
    setChooseAccountsExpanded,
  ]);

  return {
    metaSelectionPrefill,
    clearResumePrefill: () => setMetaSelectionPrefill(null),
    cancelResumeSavedPending: () => {
      resumeSavedPendingRef.current = false;
    },
    metaAssetsLoaded,
    retainedResumeSelection,
  };
}

'use client';

/**
 * Meta grant checklist overlay session state (architecture card 3 / U6).
 * Optimistic overlay + funnel analytics stay here; the wizard only wires props.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { MetaSelectionBlob } from '@/components/client-auth/meta-selection-blob';
import type { MetaAssetDecline, MetaFulfillmentResult } from '@agency-platform/shared';
import { trackClientFinishClickedWithPending, trackClientGrantChecklistViewed } from '@/lib/analytics/invite-events';
import {
  buildMetaGrantChecklist,
  type MetaGrantItemState,
} from '@/lib/invite/meta-grant-checklist';
import { metaGrantSelectedKindsFromBlob } from '@/components/client-auth/MetaGrantChecklist';
import { getMetaFollowUpLines } from '@/lib/invite/product-selection-summary';
import { resolveMetaGrantPhaseHeader } from '@/lib/invite/client-invite-status';

export interface UseMetaGrantChecklistOverlayArgs {
  platform: string;
  metaNeedsGrantStep: boolean;
  currentStep: number;
  connectionId: string | null;
  metaFulfillment?: MetaFulfillmentResult[];
  metaDeclines?: MetaAssetDecline[];
  metaAdAssets: MetaSelectionBlob;
  onRequestRefresh?: () => void;
  onComplete: () => void;
}

export interface UseMetaGrantChecklistOverlayResult {
  checklistOverlay: Record<string, MetaGrantItemState>;
  clearChecklistOverlay: () => void;
  metaChecklist: ReturnType<typeof buildMetaGrantChecklist>;
  handleItemSettled: (kind: string, state: MetaGrantItemState) => void;
  handleFinishClick: () => void;
  hasMetaFollowUp: boolean;
  metaGrantPhaseHeader: ReturnType<typeof resolveMetaGrantPhaseHeader> | null;
}

export function useMetaGrantChecklistOverlay({
  platform,
  metaNeedsGrantStep,
  currentStep,
  connectionId,
  metaFulfillment,
  metaDeclines,
  metaAdAssets,
  onRequestRefresh,
  onComplete,
}: UseMetaGrantChecklistOverlayArgs): UseMetaGrantChecklistOverlayResult {
  const [checklistOverlay, setChecklistOverlay] = useState<Record<string, MetaGrantItemState>>({});

  const metaChecklist = useMemo(
    () =>
      buildMetaGrantChecklist({
        rows: metaFulfillment,
        declines: metaDeclines,
        selectedKinds: metaGrantSelectedKindsFromBlob(metaAdAssets),
        overlay: checklistOverlay,
      }),
    [metaFulfillment, metaDeclines, metaAdAssets, checklistOverlay]
  );

  const hasReportedChecklistViewRef = useRef(false);
  useEffect(() => {
    if (!(platform === 'meta' && metaNeedsGrantStep && currentStep === 3 && connectionId)) return;
    if (hasReportedChecklistViewRef.current) return;
    hasReportedChecklistViewRef.current = true;
    trackClientGrantChecklistViewed({ remaining_count: metaChecklist.remainingCount });
  }, [platform, metaNeedsGrantStep, currentStep, connectionId, metaChecklist.remainingCount]);

  const handleItemSettled = useCallback(
    (kind: string, state: MetaGrantItemState) => {
      setChecklistOverlay((prev) => ({ ...prev, [kind]: state }));
      onRequestRefresh?.();
    },
    [onRequestRefresh]
  );

  const handleFinishClick = useCallback(() => {
    if (metaChecklist.remainingCount > 0) {
      trackClientFinishClickedWithPending({ remaining_count: metaChecklist.remainingCount });
    }
    onComplete();
  }, [metaChecklist.remainingCount, onComplete]);

  const hasMetaFollowUp =
    platform === 'meta' &&
    (metaChecklist.remainingCount > 0 ||
      getMetaFollowUpLines(metaAdAssets || {}, metaChecklist).length > 0);

  const metaGrantPhaseHeader =
    platform === 'meta' && metaNeedsGrantStep
      ? resolveMetaGrantPhaseHeader(metaChecklist)
      : null;

  return {
    checklistOverlay,
    clearChecklistOverlay: () => setChecklistOverlay({}),
    metaChecklist,
    handleItemSettled,
    handleFinishClick,
    hasMetaFollowUp,
    metaGrantPhaseHeader,
  };
}

